"""fstab_parse: parse an fstab snapshot into unified mount records."""
import re

_FIELD_ORDER = ("device", "mount", "fstype", "options")
_ESCAPES = {"040": " ", "011": "\t", "134": "\\"}
_ESCAPE_RE = re.compile(r"\\(040|011|134)")


def _business(payload):
    """Unwrap {name,result} envelopes to the business payload."""
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def _decode(text):
    return _ESCAPE_RE.sub(lambda m: _ESCAPES[m.group(1)], text)


def _options(text):
    return sorted(set(text.split(",")))


def _require_str(container, key):
    if not isinstance(container, dict):
        raise ValueError("payload must be an object")
    if key not in container:
        raise ValueError("missing required field: %s" % (key,))
    value = container[key]
    if not isinstance(value, str):
        raise ValueError("field %s must be a string" % (key,))
    return value


def _check_contract(contract, payloads):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list) or len(inputs) != len(payloads):
        raise ValueError("payload count does not match contract inputs")
    name = contract.get("name")
    if not isinstance(name, str) or not name.strip():
        raise ValueError("contract name must be a non-empty string")
    return name


def _records(text):
    records = []
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        columns = line.split()
        if not 4 <= len(columns) <= 6:
            raise ValueError("fstab line must have 4 to 6 columns: %r" % (raw,))
        device = _decode(columns[0])
        mount = _decode(columns[1])
        fstype = _decode(columns[2])
        options = _decode(columns[3])
        for field, value in zip(_FIELD_ORDER, (device, mount, fstype)):
            if not value.strip():
                raise ValueError("fstab field %s must be non-empty" % (field,))
        records.append({
            "device": device,
            "mount": mount,
            "fstype": fstype,
            "options": _options(options),
        })
    return records


def transform(payloads, contract):
    name = _check_contract(contract, payloads)
    text = _require_str(_business(payloads[0]), "fstab")
    return {"name": name, "result": {"records": _records(text)}}

