{"content":""""mount_merge: merge parsed snapshots by fixed source priority."""
from pathlib import Path

_PRIORITY = ("fstab", "aix", "mount")
_FIELDS = ("device", "fstype", "options")
_RECORD_FIELDS = ("device", "mount", "fstype", "options")


def _unwrap(payload):
    """Return (business_payload, envelope_name) for a payload."""
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"], payload["name"]
    return payload, None


def _check_contract(contract, payloads):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list) or len(inputs) != len(payloads):
        raise ValueError("payload count does not match contract inputs")
    name = contract.get("name")
    if not isinstance(name, str) or not name.strip():
        raise ValueError("contract name must be a non-empty string")
    for path in inputs:
        if not isinstance(path, str) or not path.strip():
            raise ValueError("contract inputs must be non-empty strings")
    return name


def _validate_records(data, source):
    if not isinstance(data, dict):
        raise ValueError("input from %r must be an object" % (source,))
    if "records" not in data:
        raise ValueError("input from %r is missing records" % (source,))
    records = data["records"]
    if not isinstance(records, list):
        raise ValueError("records from %r must be a list" % (source,))
    validated = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("record from %r must be an object" % (source,))
        clean = {}
        for field in _RECORD_FIELDS:
            if field not in record:
                raise ValueError("record from %r is missing %s" % (source, field))
            value = record[field]
            if field == "options":
                if not isinstance(value, list):
                    raise ValueError("options from %r must be a list" % (source,))
                for option in value:
                    if not isinstance(option, str):
                        raise ValueError("options from %r must be strings" % (source,))
                clean[field] = list(value)
            else:
                if not isinstance(value, str):
                    raise ValueError("%s from %r must be a string" % (field, source))
                if not value.strip():
                    raise ValueError("%s from %r must be non-empty" % (field, source))
                clean[field] = value
        validated.append(clean)
    return validated


def _source_priority(source, position):
    try:
        return (_PRIORITY.index(source), position)
    except ValueError:
        return (len(_PRIORITY), position)


def transform(payloads, contract):
    name = _check_contract(contract, payloads)
    entries = []  # (priority, position, order, source, record)
    order = 0
    for position, payload in enumerate(payloads):
        data, envelope_name = _unwrap(payload)
        source = envelope_name
        if not isinstance(source, str) or not source.strip():
            source = Path(contract["inputs"][position]).stem
        priority = _source_priority(source, position)
        for record in _validate_records(data, source):
            entries.append((priority[0], priority[1], order, source, record))
            order += 1
    entries.sort(key=lambda e: (e[0], e[1], e[2]))

    by_mount = {}
    for entry in entries:
        by_mount.setdefault(entry[4]["mount"], []).append(entry)

    records = []
    conflicts = []
    for mount in sorted(by_mount):
        group = by_mount[mount]
        winner = group[0][4]
        records.append(dict(winner, source=group[0][3]))
        signature = tuple(winner[field] for field in _FIELDS)
        if any(tuple(entry[4][field] for field in _FIELDS) != signature
               for entry in group[1:]):
            evidence = [dict(entry[4], source=entry[3]) for entry in group]
            conflicts.append({"mount": mount, "evidence": evidence})
    return {"name": name,
            "result": {"records": records, "conflicts": conflicts}}
