{"content":""""Orchestrate every component from its file contract, then integrate."""
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _safe_rel(path):
    if not isinstance(path, str) or not path:
        raise ValueError("path must be a non-empty string")
    if "\\" in path or ":" in path or path.startswith("/"):
        raise ValueError("unsafe path: %r" % (path,))
    parts = path.split("/")
    if any(part in ("", ".", "..") for part in parts):
        raise ValueError("unsafe path: %r" % (path,))
    return path


def _load_contracts():
    contracts = []
    for contract_path in sorted(ROOT.rglob("contract.json")):
        relative = contract_path.relative_to(ROOT)
        if "outputs" in relative.parts:
            continue
        contract = json.loads(contract_path.read_text(encoding="utf-8"))
        if not isinstance(contract, dict):
            raise ValueError("contract must be an object: %s" % (contract_path,))
        name = contract.get("name")
        if not isinstance(name, str) or not name.strip():
            raise ValueError("contract name must be a non-empty string")
        inputs = contract.get("inputs")
        if not isinstance(inputs, list) or not inputs:
            raise ValueError("contract inputs must be a non-empty list")
        for item in inputs:
            _safe_rel(item)
        _safe_rel(contract.get("output"))
        if not (contract_path.parent / "render.py").is_file():
            raise ValueError("missing render.py for %s" % (name,))
        contracts.append((name, contract, contract_path.parent))
    if not contracts:
        raise ValueError("no contracts found")
    names = [name for name, _, _ in contracts]
    if len(set(names)) != len(names):
        raise ValueError("duplicate component names")
    return contracts


def _order(contracts):
    """Topologically order components by output/input file dependencies."""
    produced = {contract["output"]: index for index, (_, contract, _) in
                enumerate(contracts)}
    dependencies = []
    for index, (_, contract, _) in enumerate(contracts):
        deps = set()
        for item in contract["inputs"]:
            producer = produced.get(item)
            if producer is not None and producer != index:
                deps.add(producer)
            elif producer is None and not (ROOT / item).is_file():
                raise ValueError("missing dependency %r" % (item,))
        dependencies.append(deps)
    order = []
    state = [0] * len(contracts)  # 0=pending, 1=in progress, 2=done
    def visit(index):
        if state[index] == 2:
            return
        if state[index] == 1:
            raise ValueError("dependency cycle detected")
        state[index] = 1
        for dep in sorted(dependencies[index]):
            visit(dep)
        state[index] = 2
        order.append(index)
    for index in range(len(contracts)):
        visit(index)
    return [contracts[index] for index in order]


def _run(command):
    result = subprocess.run(command, cwd=ROOT)
    if result.returncode != 0:
        raise ValueError("subcommand failed: %r" % (command,))


def main():
    contracts = _order(_load_contracts())
    for _, contract, directory in contracts:
        _run([sys.executable, str(directory / "render.py")])
        output = ROOT / contract["output"]
        if not output.is_file():
            raise ValueError("component did not produce %r" % (contract["output"],))
    _run([sys.executable, str(ROOT / "integrate.py")])
    _run([sys.executable, str(ROOT / "final_report.py")])


if __name__ == "__main__":
    main()
