{"content":""""Build outputs/final_report.json from the integrated core manifest."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
TITLE = "三种挂载格式的离线事实归并"
FALSE_KEYS = ("complete", "checkout", "committed", "ok")
NONEMPTY_KEYS = ("unavailable", "missing", "conflicts", "unreachable")


def _load_core():
    core = json.loads((ROOT / "outputs" / "core_manifest.json").read_text(
        encoding="utf-8"))
    if not isinstance(core, dict) or set(core) != {"components"}:
        raise ValueError("core manifest must contain exactly components")
    components = core["components"]
    if not isinstance(components, dict):
        raise ValueError("components must be an object")
    return core


def _attention(components):
    flagged = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            flagged.add(name)
        for key in FALSE_KEYS:
            if key in result and result[key] is False:
                flagged.add(name)
        for key in NONEMPTY_KEYS:
            if key in result and result[key]:
                flagged.add(name)
    return sorted(flagged)


def _sha256(core):
    payload = json.dumps(core, ensure_ascii=False, sort_keys=True,
                         separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def main():
    core = _load_core()
    report = {
        "title": TITLE,
        "component_count": len(core["components"]),
        "sha256": _sha256(core),
        "attention": _attention(core["components"]),
    }
    target = ROOT / "outputs" / "final_report.json"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(report, ensure_ascii=False, sort_keys=True,
                                 indent=2, allow_nan=False) + "\n",
                      encoding="utf-8")


if __name__ == "__main__":
    main()
","file_path":"/app/final_report.py"}

